import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { uv, hash, texture, uniform, vec2, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  const colors =
    config.intent?.visualSpec?.colors ??
    { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  // Engineered gradient scrim behind the orb plane (prevents flat void, sets the stage tone).
  const scrimGeo = new THREE.PlaneGeometry(7.2, 6.0);
  const scrimMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const c0 = new THREE.Color(colors.surface);
  const c1 = new THREE.Color(colors.ink);
  const gradY = uv().y;
  scrimMat.colorNode = mix(vec3(c0), vec3(c1), smoothstep(0.0, 1.0, gradY));
  scrimMat.opacityNode = uniform(0.55);
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, 0, -0.15);
  group.add(scrim);

  // Decorative orb plane (512x320 -> 1.6:1 aspect).
  const w = 3.2, h = 2.0;
  const planeGeo = new THREE.PlaneGeometry(w, h);
  const mat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const plane = new THREE.Mesh(planeGeo, mat);
  plane.position.set(0, 0, 0);
  group.add(plane);

  const fade = uniform(0.0);
  let loadedTex = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    loadedTex = tex;

    const t = texture(tex);
    // Subtle engineered grain.
    const grain = hash(uv().mul(vec2(900.0, 560.0))).sub(0.5).mul(0.025);
    // Soft vignette to seat the orb into the dark stage.
    const d = uv().sub(0.5).length();
    const vig = smoothstep(0.42, 0.9, d).mul(0.28);

    mat.colorNode = t.rgb.add(vec3(grain)).sub(vec3(vig));
    mat.opacityNode = t.a.mul(fade);
    mat.needsUpdate = true;

    // Gentle weighted-settle entrance.
    gsap.to(fade, { value: 1.0, duration: 0.7, ease: 'power2.out' });
    gsap.fromTo(
      plane.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }
    );
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    gsap.killTweensOf(fade);
    gsap.killTweensOf(plane.scale);
    planeGeo.dispose();
    scrimGeo.dispose();
    mat.dispose();
    scrimMat.dispose();
    if (loadedTex) loadedTex.dispose();
  };

  return group;
}
